{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Codeine, the closest structural analog (3-methoxy-6-hydroxy-7,8-didehydro-4,5-epoxymorphinan), has an absolute oral bioavailability of 42–71% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Codeine oral bioavailability was estimated at 84 ± 5% (range 74–94%) from published pharmacokinetic data, supporting high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Codeine is 60–70% orally bioavailable in humans, with substantial but incomplete presystemic metabolism, still far above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ethylmorphine, another 3-alkoxy-6-hydroxy morphinan closely related to the query, has a median minimum oral availability of 0.74 (range 0.54–0.92) in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Morphine, the 3-hydroxy analog of the query, has an absolute oral bioavailability of 32% from immediate-release tablets; the query's 3-methoxy group typically increases oral bioavailability relative to morphine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Codeine sulfate, a 6-sulfate ester of the codeine scaffold, shows 80.5% oral bioavailability in healthy subjects, indicating the morphinan core is well absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4,5-epoxymorphinan essentially identical in core structure to codeine (3-methoxy, 6-hydroxy, N-methyl, 7,8-didehydro). Codeine and close morphinan analogs consistently show oral bioavailability values of 28–100%, all above the 20% threshold. Structurally distant low-bioavailability compounds (cepharanthine, M6G) are not transferable. Therefore, the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact stereoisomer of the query; the C13/C14 ring-junction stereochemistry differs slightly from codeine.",
    "Most records do not specify the fasted state, though codeine bioavailability is not strongly food-dependent.",
    "The impact of the query's specific stereochemistry on first-pass metabolism (e.g., glucuronidation, CYP2D6 O-demethylation) is not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C21", "C25", "C49", "C08", "C17", "C20"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "morphinan opioids"
    },
    {
      "applicability": "low",
      "card_ids": ["C42", "C47"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "structurally distant low-F compounds"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C12", "C45"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "N-methyl piperidine opioids"
    }
  ],
  "revision_action": "initial"
}

